  ('60000000-0000-0000-0000-000000000004', NULL, 'EXERCISE_TEMPLATE', 'Cuốn tạ bắp tay (Bicep Curl)', 'Bài tập mẫu cho demo sửa tư thế bằng camera real-time; giữ thân người ổn định khi gập khuỷu tay.', 0, 'ALL', TRUE, 1, '2026-08-04T02:00:00.000Z'::timestamptz, NULL, '{"difficulty":"EASY","durationMinutes":5,"supportsPostureAnalysis":true}'::jsonb, '885dee244ac71c4e325eb18f4e7aace2fe33775287db73425177cd1975bf2f0a', '2026-08-04T02:00:00.000Z'::timestamptz, '2026-08-04T02:00:00.000Z'::timestamptz, '10000000-0000-0000-0000-000000000001', 'EASY', 5, 'Đứng thẳng, giữ khuỷu tay gần thân, từ từ cuốn tay lên rồi hạ xuống có kiểm soát. Tập trong phạm vi thoải mái và không nín thở.', NULL, 'Dữ liệu demo ML, không thay thế tư vấn y tế. Dừng lại nếu đau, chóng mặt, khó thở hoặc có dấu hiệu bất thường; hỏi nhân viên y tế trước khi tập.', TRUE, 'PUBLISHED', NULL, NULL, NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MANDATORY', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('60000000-0000-0000-0000-000000000005', NULL, 'EXERCISE_TEMPLATE', 'Plank cơ bản', 'Bài tập mẫu cho demo sửa tư thế; giữ thân người thành một đường thẳng trong thời gian ngắn.', 0, 'ALL', TRUE, 1, '2026-08-04T02:00:00.000Z'::timestamptz, NULL, '{"difficulty":"MEDIUM","durationMinutes":3,"supportsPostureAnalysis":true}'::jsonb, '1264f5750c7ccb9cc7d94002b142330c591ed0eebc6111b6b9deaceb7c4a6981', '2026-08-04T02:00:00.000Z'::timestamptz, '2026-08-04T02:00:00.000Z'::timestamptz, '10000000-0000-0000-0000-000000000001', 'MEDIUM', 3, 'Chống khuỷu tay hoặc hai tay, siết nhẹ cơ bụng, giữ hông không võng và thở đều. Có thể hạ gối để giảm tải.', NULL, 'Dữ liệu demo ML, không thay thế tư vấn y tế. Dừng lại nếu đau lưng, đau bụng, khó thở hoặc thấy không thoải mái; hỏi nhân viên y tế trước khi tập.', TRUE, 'PUBLISHED', NULL, NULL, NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MANDATORY', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('60000000-0000-0000-0000-000000000006', NULL, 'EXERCISE_TEMPLATE', 'Squat cơ bản', 'Bài tập mẫu cho demo sửa tư thế; luyện pha đứng và hạ người có kiểm soát.', 0, 'ALL', TRUE, 1, '2026-08-04T02:00:00.000Z'::timestamptz, NULL, '{"difficulty":"MEDIUM","durationMinutes":5,"supportsPostureAnalysis":true}'::jsonb, 'a7abcb1d4be12ebcd4ebde0fe27f50e5260e4d606e34a14e4f595222b4c0cc31', '2026-08-04T02:00:00.000Z'::timestamptz, '2026-08-04T02:00:00.000Z'::timestamptz, '10000000-0000-0000-0000-000000000001', 'MEDIUM', 5, 'Đứng chân rộng bằng vai, đẩy hông ra sau, hạ người trong phạm vi thoải mái rồi đứng lên. Giữ gối hướng theo mũi chân và lưng trung tính.', NULL, 'Dữ liệu demo ML, không thay thế tư vấn y tế. Dừng lại nếu đau gối, đau lưng, chóng mặt hoặc có dấu hiệu bất thường; hỏi nhân viên y tế trước khi tập.', TRUE, 'PUBLISHED', NULL, NULL, NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MANDATORY', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('60000000-0000-0000-0000-000000000007', NULL, 'EXERCISE_TEMPLATE', 'Lunge bước chùng', 'Bài tập mẫu cho demo sửa tư thế; theo dõi vị trí gối và pha hạ người.', 0, 'ALL', TRUE, 1, '2026-08-04T02:00:00.000Z'::timestamptz, NULL, '{"difficulty":"MEDIUM","durationMinutes":5,"supportsPostureAnalysis":true}'::jsonb, 'a7abcb1d4be12ebcd4ebde0fe27f50e5260e4d606e34a14e4f595222b4c0cc31', '2026-08-04T02:00:00.000Z'::timestamptz, '2026-08-04T02:00:00.000Z'::timestamptz, '10000000-0000-0000-0000-000000000001', 'MEDIUM', 5, 'Bước một chân lên trước, hạ người chậm và đẩy trở lại vị trí ban đầu. Giữ thân người thẳng, gối trước hướng theo mũi chân và bám điểm tựa nếu cần.', NULL, 'Dữ liệu demo ML, không thay thế tư vấn y tế. Chỉ tập khi đã được nhân viên y tế cho phép; dừng lại nếu đau, mất thăng bằng, chóng mặt hoặc khó thở.', TRUE, 'PUBLISHED', NULL, NULL, NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MANDATORY', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
